def commons_search(query: str, limit: int) -> list[str]:
    params = {
        "action": "query",
        "format": "json",
        "generator": "search",
        "gsrsearch": f"filetype:bitmap {query}",
        "gsrnamespace": "6",
        "gsrlimit": str(limit),
        "prop": "imageinfo",
        "iiprop": "url|mime|size",
        "iiurlwidth": "800",
    }
    url = "https://commons.wikimedia.org/w/api.php?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(url, headers={"User-Agent": UA})
    with urllib.request.urlopen(req, timeout=30) as resp:
        data = json.loads(resp.read().decode("utf-8"))
    pages = data.get("query", {}).get("pages", {})
    urls = []
    for page in pages.values():
        info = (page.get("imageinfo") or [{}])[0]
        mime = info.get("mime", "")
        if mime not in {"image/jpeg", "image/png"}:
            continue
        file_url = info.get("thumburl") or info.get("url")
        if file_url:
            urls.append(file_url)
    return urls


def download(url: str, dest: Path) -> bool:
    req = urllib.request.Request(url, headers={"User-Agent": UA})
    try:
        with urllib.request.urlopen(req, timeout=40) as resp:
            data = resp.read()
        if len(data) < 2000:
            return False
        dest.write_bytes(data)
        return True
    except Exception:
        return False


def main(download_photos: bool = True) -> None:
    fill_items()
    rest_items()
    if download_photos:
        PHOTOS.mkdir(parents=True, exist_ok=True)
    catalog = {"groups": []}
    for group in GROUPS:
        g = {"name": group["name"], "subgroups": []}
        for sg in group["subgroups"]:
            items = ITEMS.get(sg, [])
            if not (15 <= len(items) <= 30):
                raise SystemExit(f"{sg}: {len(items)} items")
            props = PROPS[sg]
            if not (5 <= len(props) <= 10):
                raise SystemExit(f"{sg}: {len(props)} properties")
            urls = []
            if download_photos:
                urls = commons_search(PHOTO_QUERIES[sg], max(len(items) + 8, 20))
                time.sleep(0.4)
            sg_obj = {"name": sg, "properties": props, "items": []}
            for i, (name, brand, model, values) in enumerate(items):
                fname = ""
                if download_photos:
                    fname = f"{slug(sg)}-{i+1:02d}.jpg"
                    dest = PHOTOS / fname
                    ok = False
                    if i < len(urls):
                        ok = download(urls[i], dest)
                    if not ok and urls:
                        ok = download(urls[i % len(urls)], dest)
                    if not dest.exists():
                        fname = ""
                sg_obj["items"].append(
                    {
                        "name": name[:150],
                        "brand": brand[:20],
                        "model": model[:20],
                        "photo": fname,
                        "properties": values,
                    }
                )
            g["subgroups"].append(sg_obj)
            print(sg, len(items), "props", len(props))
        catalog["groups"].append(g)
    JSON_OUT.parent.mkdir(parents=True, exist_ok=True)
    JSON_OUT.write_text(json.dumps(catalog, ensure_ascii=False, indent=2), encoding="utf-8")
    print("wrote", JSON_OUT)


if __name__ == "__main__":
    import sys
    main(download_photos="--no-photos" not in sys.argv)
